  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core_dist = case['core_distance']
    dist_list = case['distances']

    # Build distance lookup
    dist = {}
    for u, v, d in dist_list:
        # store both directions for quick access
        key = (u, v) if u <= v else (v, u)
        dist[key] = d

    # Compute all mutual reachability edges
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i+1, n):
            u = nodes[i]
            v = nodes[j]
            d = dist.get((u, v), float('inf'))
            if d == float('inf'):
                continue  # missing pair, skip (should not happen)
            w = max(core_dist[u], core_dist[v], d)
            edges.append((w, u, v))

    # Sort deterministically by weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            # Ensure consistent order: smaller node string first
            if u < v:
                mst_edges.append([u, v, w])
            else:
                mst_edges.append([v, u, w])
            total_weight += w

    return {'mst_edges': mst_edges, 'total_weight': total_weight}
